use clap::Parser;
use std::fs::File;
use std::io::{self, Read, BufRead, BufReader, Write};
use std::path::Path;

#[derive(Parser)]
#[command(name = "b3sum")]
#[command(version = "1.8.4")]
#[command(about = "BLAKE3 hash utility")]
#[command(author)]
struct Args {
    /// Files to hash, or checkfiles to check. When no file is given, or when - is given, read standard input.
    #[arg(value_name = "FILE")]
    files: Vec<String>,

    /// Use the keyed mode, reading the 32-byte key from stdin
    #[arg(long)]
    keyed: bool,

    /// Use the key derivation mode, with the given context string. Cannot be used with --keyed.
    #[arg(long)]
    derive_key: Option<String>,

    /// The number of output bytes, before hex encoding
    #[arg(short = 'l', long, default_value = "32")]
    length: usize,

    /// The starting output byte offset, before hex encoding
    #[arg(long, default_value = "0")]
    seek: usize,

    /// The maximum number of threads to use. By default, this is the number of logical cores.
    #[arg(long)]
    num_threads: Option<usize>,

    /// Disable memory mapping. Currently this also disables multithreading.
    #[arg(long)]
    no_mmap: bool,

    /// Omit filenames in the output
    #[arg(long)]
    no_names: bool,

    /// Write raw output bytes to stdout, rather than hex. --no-names is implied.
    #[arg(long)]
    raw: bool,

    /// Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]
    #[arg(long)]
    tag: bool,

    /// Read BLAKE3 sums from the [FILE]s and check them
    #[arg(short = 'c', long)]
    check: bool,

    /// Skip printing OK for each checked file. Must be used with --check.
    #[arg(long)]
    quiet: bool,
}

fn main() {
    let args = Args::parse();

    if args.quiet && !args.check {
        eprintln!("error: --quiet must be used with --check");
        std::process::exit(1);
    }

    if args.keyed && args.derive_key.is_some() {
        eprintln!("error: --keyed and --derive-key cannot be used together");
        std::process::exit(1);
    }

    if args.raw && args.files.len() > 1 {
        eprintln!("error: --raw cannot be used with multiple inputs");
        std::process::exit(1);
    }

    // Set number of threads if specified
    if let Some(num_threads) = args.num_threads {
        if num_threads > 0 {
            rayon::ThreadPoolBuilder::new()
                .num_threads(num_threads)
                .build_global()
                .ok();
        }
    }

    if args.check {
        check_hashes(&args);
    } else {
        hash_files(&args);
    }
}

fn hash_files(args: &Args) {
    let files = if args.files.is_empty() {
        vec!["-".to_string()]
    } else {
        args.files.clone()
    };

    let use_stdin = args.keyed || args.derive_key.is_some();
    let mut stdin_data = Vec::new();

    if use_stdin {
        if io::stdin().read_to_end(&mut stdin_data).is_err() {
            eprintln!("error reading from stdin");
            std::process::exit(1);
        }
    }

    for (i, file_path) in files.iter().enumerate() {
        if args.raw && i > 0 {
            eprintln!("error: --raw cannot be used with multiple inputs");
            std::process::exit(1);
        }

        let file_data = if file_path == "-" {
            if use_stdin {
                stdin_data.clone()
            } else {
                let mut data = Vec::new();
                if io::stdin().read_to_end(&mut data).is_err() {
                    eprintln!("error reading from stdin");
                    std::process::exit(1);
                }
                data
            }
        } else {
            match std::fs::read(file_path) {
                Ok(data) => data,
                Err(e) => {
                    eprintln!("error reading file '{}': {}", file_path, e);
                    std::process::exit(1);
                }
            }
        };

        let hash = if args.keyed {
            if stdin_data.len() != 32 {
                eprintln!("error: keyed mode requires exactly 32 bytes of key material");
                std::process::exit(1);
            }
            let key: [u8; 32] = stdin_data[..32].try_into().unwrap();
            blake3::keyed_hash(&key, &file_data)
        } else if let Some(ref context) = args.derive_key {
            blake3::derive_key(context, &stdin_data)
        } else {
            blake3::hash(&file_data)
        };

        let output = hash_to_output(&hash, args.seek, args.length);

        if args.raw {
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            handle.write_all(&output).ok();
        } else {
            let hex = hex_encode(&output);
            if args.tag {
                let display_name = if file_path == "-" { "-" } else { file_path };
                println!("BLAKE3 ({}) = {}", display_name, hex);
            } else if args.no_names {
                println!("{}", hex);
            } else {
                let display_name = if file_path == "-" { "-" } else { file_path };
                println!("{}  {}", hex, display_name);
            }
        }
    }
}

fn check_hashes(args: &Args) {
    let files = if args.files.is_empty() {
        vec!["-".to_string()]
    } else {
        args.files.clone()
    };

    let mut all_ok = true;

    for file_path in files {
        let reader: Box<dyn BufRead> = if file_path == "-" {
            Box::new(BufReader::new(io::stdin()))
        } else {
            match File::open(&file_path) {
                Ok(f) => Box::new(BufReader::new(f)),
                Err(e) => {
                    eprintln!("error reading file '{}': {}", file_path, e);
                    std::process::exit(1);
                }
            }
        };

        for line in reader.lines() {
            if let Ok(line) = line {
                let line = line.trim();
                if line.is_empty() {
                    continue;
                }

                let (hash_str, filename) = parse_checksum_line(&line);

                if let Some(filename) = filename {
                    match std::fs::read(&filename) {
                        Ok(data) => {
                            let computed_hash = blake3::hash(&data);
                            let computed_hex = hex_encode(computed_hash.as_bytes());

                            if computed_hex == hash_str {
                                if !args.quiet {
                                    println!("{}: OK", filename);
                                }
                            } else {
                                eprintln!("{}: FAILED", filename);
                                all_ok = false;
                            }
                        }
                        Err(e) => {
                            eprintln!("error reading file '{}': {}", filename, e);
                            all_ok = false;
                        }
                    }
                } else {
                    eprintln!("error parsing checksum line: {}", line);
                    all_ok = false;
                }
            }
        }
    }

    if !all_ok {
        std::process::exit(1);
    }
}

fn parse_checksum_line(line: &str) -> (String, Option<String>) {
    // Try BSD format first: BLAKE3 (filename) = hash
    if let Some(rest) = line.strip_prefix("BLAKE3 (") {
        if let Some(idx) = rest.find(") = ") {
            let filename = rest[..idx].to_string();
            let hash = rest[idx + 4..].to_string();
            return (hash, Some(filename));
        }
    }

    // Try standard format: hash  filename
    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() >= 2 {
        let hash = parts[0].to_string();
        let filename = parts[1..].join(" ");
        return (hash, Some(filename));
    }

    (line.to_string(), None)
}

fn hash_to_output(hash: &blake3::Hash, seek: usize, length: usize) -> Vec<u8> {
    let bytes = hash.as_bytes();
    let start = seek;
    let end = (start + length).min(bytes.len());

    if start >= bytes.len() {
        vec![]
    } else {
        bytes[start..end].to_vec()
    }
}

fn hex_encode(data: &[u8]) -> String {
    data.iter()
        .map(|b| format!("{:02x}", b))
        .collect::<String>()
}
