// https://github.com/BLAKE3-team/BLAKE3/blob/master/blake3.md

use std::mem;

const BLOCKBYTES: usize = 64;
const OUTBYTES: usize = 32;
const KEY_LEN: usize = 32;
const CHAINING_VALUE_LEN: usize = 8;
const CHUNK_LEN: usize = 1024;
