    [2, 12, 6, 10, 0, 3, 12, 8, 1, 4, 13, 11, 7, 14, 5, 15],
    [0, 2, 4, 6, 8, 10, 12, 14, 1, 3, 5, 7, 9, 11, 13, 15],
];

const FLAG_CHUNK_START: u32 = 1 << 0;
const FLAG_CHUNK_END: u32 = 1 << 1;
const FLAG_PARENT: u32 = 1 << 2;
const FLAG_ROOT: u32 = 1 << 3;
const FLAG_KEYED_HASH: u32 = 1 << 4;
const FLAG_DERIVE_KEY: u32 = 1 << 5;

#[derive(Clone)]
pub struct Blake3 {
    chaining_value: [u32; 8],
    chunk_counter: u64,
    block: [u8; BLOCKBYTES],
    block_len: usize,
    blocks_compressed: u64,
    flags: u32,
    finalized: bool,
}

impl Blake3 {
    pub fn new() -> Self {
        Blake3 {
            chaining_value: IV,
            chunk_counter: 0,
            block: [0; BLOCKBYTES],
            block_len: 0,
            blocks_compressed: 0,
            flags: FLAG_CHUNK_START,
            finalized: false,
        }
    }

    pub fn new_keyed(key: &[u8; 32]) -> Self {
        let mut hasher = Blake3::new();
        hasher.chaining_value = bytes_to_state(key);
        hasher.flags |= FLAG_KEYED_HASH;
        hasher
    }

    pub fn derive_key_internal(context: &str, key_material: &[u8]) -> [u8; 32] {
        let mut hasher = Blake3::new();
        hasher.flags |= FLAG_DERIVE_KEY;
        hasher.update(context.as_bytes());
        hasher.update(key_material);
        hasher.finalize_internal()
    }

    pub fn update(&mut self, input: &[u8]) {
        if self.finalized {
            return;
        }

        let mut input_pos = 0;
        while input_pos < input.len() {
            if self.block_len == BLOCKBYTES {
                self.compress_block(false);
                self.block_len = 0;
                self.blocks_compressed += 1;
            }

            let to_copy = (BLOCKBYTES - self.block_len).min(input.len() - input_pos);
            self.block[self.block_len..self.block_len + to_copy]
                .copy_from_slice(&input[input_pos..input_pos + to_copy]);
            self.block_len += to_copy;
            input_pos += to_copy;
        }
    }

    fn compress_block(&mut self, is_final: bool) {
        let block_words = bytes_to_words(&self.block[..self.block_len]);
        let mut words = [0u32; 16];
        words[..block_words.len()].copy_from_slice(&block_words);

        let mut state = self.chaining_value;

        for round in 0..7 {
            let schedule = MSG_SCHEDULE[round];
            for i in 0..8 {
                let a = i * 2;
                let b = i * 2 + 1;
                let m_a = words[schedule[a]];
                let m_b = words[schedule[b]];

                // G function
                state[(a / 2) % 4] = state[(a / 2) % 4]
                    .wrapping_add(state[(a / 2 + 4) % 8])
                    .wrapping_add(m_a);
                state[12 + (a / 2) % 4] =
                    (state[12 + (a / 2) % 4] ^ state[(a / 2) % 4]).rotate_right(16);
                state[(a / 2 + 8) % 8] = state[(a / 2 + 8) % 8]
                    .wrapping_add(state[12 + (a / 2) % 4]);
                state[(a / 2) % 4] =
                    (state[(a / 2) % 4] ^ state[(a / 2 + 8) % 8]).rotate_right(12);

                state[(b / 2 + 2) % 4] = state[(b / 2 + 2) % 4]
                    .wrapping_add(state[(b / 2 + 6) % 8])
                    .wrapping_add(m_b);
                state[12 + (b / 2 + 2) % 4] =
                    (state[12 + (b / 2 + 2) % 4] ^ state[(b / 2 + 2) % 4]).rotate_right(16);
                state[(b / 2 + 10) % 8] = state[(b / 2 + 10) % 8]
                    .wrapping_add(state[12 + (b / 2 + 2) % 4]);
                state[(b / 2 + 2) % 4] = (state[(b / 2 + 2) % 4] ^ state[(b / 2 + 10) % 8])
                    .rotate_right(12);
            }
        }

        for i in 0..8 {
            self.chaining_value[i] ^= state[i] ^ state[i + 8];
        }
    }

    pub fn finalize_internal(&mut self) -> [u8; 32] {
        if !self.finalized {
            if self.block_len > 0 {
                self.compress_block(true);
            }
            self.finalized = true;
        }

        let mut output = [0u8; 32];
        for (i, &word) in self.chaining_value.iter().enumerate() {
            output[i * 4..(i + 1) * 4].copy_from_slice(&word.to_le_bytes());
        }
        output
    }

    pub fn finalize(&mut self) -> [u8; 32] {
        self.finalize_internal()
    }
}

fn bytes_to_state(bytes: &[u8; 32]) -> [u32; 8] {
    let mut state = [0u32; 8];
    for i in 0..8 {
        state[i] = u32::from_le_bytes([
            bytes[i * 4],
            bytes[i * 4 + 1],
            bytes[i * 4 + 2],
            bytes[i * 4 + 3],
        ]);
    }
    state
}

fn bytes_to_words(bytes: &[u8]) -> Vec<u32> {
    let mut words = Vec::new();
    for chunk in bytes.chunks(4) {
        let mut word = [0u8; 4];
        for (i, &byte) in chunk.iter().enumerate() {
            word[i] = byte;
        }
        words.push(u32::from_le_bytes(word));
    }
    words
}

pub fn hash(data: &[u8]) -> [u8; 32] {
    let mut hasher = Blake3::new();
    hasher.update(data);
    hasher.finalize()
}

pub fn keyed_hash(key: &[u8; 32], data: &[u8]) -> [u8; 32] {
    let mut hasher = Blake3::new_keyed(key);
    hasher.update(data);
    hasher.finalize()
}

pub fn derive_key(context: &str, key_material: &[u8]) -> [u8; 32] {
    Blake3::derive_key_internal(context, key_material)
}
