mod blake3;

use std::env;
use std::fs::File;
use std::io::{self, Read, BufRead, BufReader, Write};
use std::path::Path;

#[derive(Debug)]
struct Args {
    files: Vec<String>,
    keyed: bool,
    derive_key: Option<String>,
    length: usize,
    seek: usize,
    num_threads: Option<usize>,
    no_mmap: bool,
    no_names: bool,
    raw: bool,
    tag: bool,
    check: bool,
    quiet: bool,
    help: bool,
    version: bool,
}

impl Args {
    fn from_args() -> Self {
        let args: Vec<String> = env::args().collect();
        let mut parsed = Args {
            files: Vec::new(),
            keyed: false,
            derive_key: None,
            length: 32,
            seek: 0,
            num_threads: None,
            no_mmap: false,
            no_names: false,
            raw: false,
            tag: false,
            check: false,
            quiet: false,
            help: false,
            version: false,
        };

        let mut i = 1;
        while i < args.len() {
            let arg = &args[i];

            if arg == "-h" || arg == "--help" {
                parsed.help = true;
                return parsed;
            } else if arg == "-V" || arg == "--version" {
                parsed.version = true;
                return parsed;
            } else if arg == "--keyed" {
                parsed.keyed = true;
            } else if arg == "--derive-key" {
                i += 1;
                if i < args.len() {
                    parsed.derive_key = Some(args[i].clone());
                }
            } else if arg == "-l" || arg == "--length" {
                i += 1;
                if i < args.len() {
                    if let Ok(len) = args[i].parse() {
                        parsed.length = len;
                    }
                }
            } else if arg == "--seek" {
                i += 1;
                if i < args.len() {
                    if let Ok(seek) = args[i].parse() {
                        parsed.seek = seek;
                    }
                }
            } else if arg == "--num-threads" {
                i += 1;
                if i < args.len() {
                    if let Ok(threads) = args[i].parse() {
                        parsed.num_threads = Some(threads);
                    }
                }
            } else if arg == "--no-mmap" {
                parsed.no_mmap = true;
            } else if arg == "--no-names" {
                parsed.no_names = true;
            } else if arg == "--raw" {
                parsed.raw = true;
            } else if arg == "--tag" {
                parsed.tag = true;
            } else if arg == "-c" || arg == "--check" {
                parsed.check = true;
