fn compress(cv: &[u32; 8], block: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 8] {
    let mut state = [
        cv[0], cv[1], cv[2], cv[3],
        cv[4], cv[5], cv[6], cv[7],
        IV[0], IV[1], IV[2], IV[3],
        IV[4], IV[5], IV[6], IV[7],
    ];

    state[12] ^= counter as u32;
    state[13] ^= (counter >> 32) as u32;
    state[14] ^= block_len;
    state[15] ^= flags;

    for round in 0..7 {
        let s = &SIGMA[round];

        // Row 0
        g(&mut state, 0, 4, 8, 12, block[s[0]], block[s[1]]);
        // Row 1
        g(&mut state, 1, 5, 9, 13, block[s[2]], block[s[3]]);
        // Row 2
        g(&mut state, 2, 6, 10, 14, block[s[4]], block[s[5]]);
        // Row 3
        g(&mut state, 3, 7, 11, 15, block[s[6]], block[s[7]]);

        // Diagonal 0
        g(&mut state, 0, 5, 10, 15, block[s[8]], block[s[9]]);
        // Diagonal 1
        g(&mut state, 1, 6, 11, 12, block[s[10]], block[s[11]]);
        // Diagonal 2
        g(&mut state, 2, 7, 8, 13, block[s[12]], block[s[13]]);
        // Diagonal 3
        g(&mut state, 3, 4, 9, 14, block[s[14]], block[s[15]]);
    }

    let mut out = [0u32; 8];
    for i in 0..8 {
        out[i] = cv[i] ^ state[i] ^ state[i + 8];
    }
    out
}

#[inline]
fn g(state: &mut [u32], a: usize, b: usize, c: usize, d: usize, x: u32, y: u32) {
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(x);
    state[d] = (state[d] ^ state[a]).rotate_right(16);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(12);
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(y);
    state[d] = (state[d] ^ state[a]).rotate_right(8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(7);
}

pub fn hash(data: &[u8]) -> Hash {
    let mut h = Hasher::new();
    h.update(data);
    h.finalize()
}

pub fn keyed_hash(key: &[u8; 32], data: &[u8]) -> Hash {
    let mut h = Hasher::new_keyed(key);
    h.update(data);
    h.finalize()
}

pub fn derive_key(context: &str, key_material: &[u8]) -> [u8; 32] {
    let mut h = Hasher::new();
    h.flags |= FLAG_DERIVE_KEY;
    h.update(context.as_bytes());
    h.update(key_material);
    let hash = h.finalize();
    let mut result = [0u8; 32];
    result.copy_from_slice(hash.as_bytes());
    result
}
