                self.buf_len = 0;
                self.flags &= !FLAG_CHUNK_START;
            }

            // Fill buffer
            let n = (BLOCK_LEN - self.buf_len).min(data.len());
            self.buf[self.buf_len..self.buf_len + n].copy_from_slice(&data[..n]);
            self.buf_len += n;
            data = &data[n..];
        }
    }

    pub fn finalize(&self) -> Hash {
        let mut h = self.clone();

        let mut msg = [0u32; 16];
