                }
                msg[i] = u32::from_le_bytes(bytes);
            }
        }

        let flags = h.flags | FLAG_CHUNK_END | FLAG_ROOT;
        let cv = compress_block(&h.cv, &msg, h.chunk_counter, h.buf_len as u32, flags);

        let mut out = [0u8; HASH_LEN];
        for (i, &word) in cv.iter().enumerate() {
            let bytes = word.to_le_bytes();
            out[i*4..i*4+4].copy_from_slice(&bytes);
        }
        Hash(out)
    }
}

fn compress_block(cv: &[u32; 8], msg: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 8] {
    let mut state = [
        cv[0], cv[1], cv[2], cv[3],
        cv[4], cv[5], cv[6], cv[7],
        IV[0], IV[1], IV[2], IV[3],
        IV[4], IV[5], IV[6], IV[7],
    ];

    state[12] ^= counter as u32;
    state[13] ^= (counter >> 32) as u32;
    state[14] ^= block_len;
    state[15] ^= flags;

    for round in 0..7 {
        let perm = MSG_PERMUTATION[round];

