        g(&mut state, 0, 4, 8, 12, msg[perm[0]], msg[perm[1]]);
        g(&mut state, 1, 5, 9, 13, msg[perm[2]], msg[perm[3]]);
        g(&mut state, 2, 6, 10, 14, msg[perm[4]], msg[perm[5]]);
        g(&mut state, 3, 7, 11, 15, msg[perm[6]], msg[perm[7]]);

        // Diagonal operations
        g(&mut state, 0, 5, 10, 15, msg[perm[8]], msg[perm[9]]);
        g(&mut state, 1, 6, 11, 12, msg[perm[10]], msg[perm[11]]);
        g(&mut state, 2, 7, 8, 13, msg[perm[12]], msg[perm[13]]);
        g(&mut state, 3, 4, 9, 14, msg[perm[14]], msg[perm[15]]);
    }

    let mut out = [0u32; 8];
    for i in 0..8 {
        out[i] = cv[i] ^ state[i] ^ state[i + 8];
    }
