    [0, 2, 4, 6, 8, 10, 12, 14, 1, 3, 5, 7, 9, 11, 13, 15],
];

const FLAG_CHUNK_START: u32 = 0x00000001;
const FLAG_CHUNK_END: u32 = 0x00000002;
const FLAG_PARENT: u32 = 0x00000004;
const FLAG_ROOT: u32 = 0x00000008;
const FLAG_KEYED_HASH: u32 = 0x00000010;
const FLAG_DERIVE_KEY: u32 = 0x00000020;

#[derive(Clone)]
pub struct Hasher {
    cv: [u32; 8],
    chunk_counter: u64,
    buf: Vec<u8>,
    flags: u32,
}

#[derive(Clone, Copy, Debug)]
pub struct Hash([u8; 32]);

impl Hash {
    pub fn as_bytes(&self) -> &[u8; 32] {
        &self.0
    }
}

impl Hasher {
    pub fn new() -> Self {
        Hasher {
            cv: IV,
            chunk_counter: 0,
            buf: Vec::new(),
            flags: FLAG_CHUNK_START,
        }
    }

    pub fn new_keyed(key: &[u8; 32]) -> Self {
        let mut h = Hasher::new();
        for i in 0..8 {
            let bytes = [key[4*i], key[4*i+1], key[4*i+2], key[4*i+3]];
            h.cv[i] = u32::from_le_bytes(bytes);
        }
        h.flags |= FLAG_KEYED_HASH;
        h
    }

    pub fn update(&mut self, mut data: &[u8]) {
        while !data.is_empty() {
            if self.buf.len() == BLOCKBYTES {
                let mut block = [0u32; 16];
                for i in 0..16 {
                    let bytes = [self.buf[4*i], self.buf[4*i+1], self.buf[4*i+2], self.buf[4*i+3]];
                    block[i] = u32::from_le_bytes(bytes);
                }
                self.cv = compress(&self.cv, &block, self.chunk_counter, BLOCKBYTES as u32, self.flags);
                self.chunk_counter += 1;
                self.buf.clear();
                self.flags &= !FLAG_CHUNK_START;
            }

            let n = (BLOCKBYTES - self.buf.len()).min(data.len());
            self.buf.extend_from_slice(&data[..n]);
            data = &data[n..];
        }
    }

    pub fn finalize(&self) -> Hash {
        let mut h = self.clone();

        // Pad the last block
        while h.buf.len() < BLOCKBYTES {
            h.buf.push(0);
        }

        let mut block = [0u32; 16];
        for i in 0..16 {
            let start = 4*i;
            let end = (start + 4).min(h.buf.len());
            let mut bytes = [0u8; 4];
            for j in start..end {
                bytes[j - start] = h.buf[j];
            }
            block[i] = u32::from_le_bytes(bytes);
        }

        let flags = h.flags | FLAG_CHUNK_END | FLAG_ROOT;
        let cv = compress(&h.cv, &block, h.chunk_counter, h.buf.len() as u32, flags);

        let mut out = [0u8; 32];
        for (i, &word) in cv.iter().enumerate() {
            let bytes = word.to_le_bytes();
            out[4*i..4*i+4].copy_from_slice(&bytes);
        }
        Hash(out)
    }
}

fn compress(cv: &[u32; 8], block: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 8] {
    let mut v = [0u32; 16];
    v[0..8].copy_from_slice(cv);
    v[8..16].copy_from_slice(&IV);

    v[12] ^= counter as u32;
    v[13] ^= (counter >> 32) as u32;
    v[14] ^= block_len;
    v[15] ^= flags;

    for round in 0..7 {
        for i in 0..8 {
            let m_2i = block[SIGMA[round][2*i]];
            let m_2i_1 = block[SIGMA[round][2*i + 1]];

            if i < 4 {
                // Column mixing
                mixing_function(&mut v, 4*i, 4*i + 1, 4*i + 2, 4*i + 3, m_2i, m_2i_1);
            } else {
                // Diagonal mixing
                let a = (i - 4) * 2;
                let b = ((i - 4) * 2 + 1) % 8;
                let c = ((i - 4) + 4) % 8;
                let d = ((i - 4) + 5) % 8;
                mixing_function(&mut v, a, b, c + 8, d + 8, m_2i, m_2i_1);
            }
        }
    }

    let mut out = [0u32; 8];
    for i in 0..8 {
        out[i] = cv[i] ^ v[i] ^ v[i + 8];
    }
    out
}

fn mixing_function(v: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, x: u32, y: u32) {
    v[a] = v[a].wrapping_add(v[b]).wrapping_add(x);
    v[d] = (v[d] ^ v[a]).rotate_right(16);
    v[c] = v[c].wrapping_add(v[d]);
    v[b] = (v[b] ^ v[c]).rotate_right(12);
    v[a] = v[a].wrapping_add(v[b]).wrapping_add(y);
    v[d] = (v[d] ^ v[a]).rotate_right(8);
    v[c] = v[c].wrapping_add(v[d]);
    v[b] = (v[b] ^ v[c]).rotate_right(7);
}

pub fn hash(data: &[u8]) -> Hash {
    let mut h = Hasher::new();
    h.update(data);
    h.finalize()
}

pub fn keyed_hash(key: &[u8; 32], data: &[u8]) -> Hash {
    let mut h = Hasher::new_keyed(key);
    h.update(data);
    h.finalize()
}

pub fn derive_key(context: &str, key_material: &[u8]) -> [u8; 32] {
    let mut h = Hasher::new();
    h.flags |= FLAG_DERIVE_KEY;
    h.update(context.as_bytes());
    h.update(key_material);
    let mut result = [0u8; 32];
    result.copy_from_slice(&h.finalize().0);
    result
}
