const FLAG_ROOT: u32 = 0x08;
const FLAG_KEYED_HASH: u32 = 0x10;
const FLAG_DERIVE_KEY: u32 = 0x20;

#[derive(Clone)]
pub struct Hasher {
    cv: [u32; 8],
    chunk_counter: u64,
    buf: [u8; BLOCK_LEN],
    buf_len: usize,
    flags: u32,
}

#[derive(Clone, Copy)]
pub struct Hash([u8; 32]);

impl Hash {
    pub fn as_bytes(&self) -> &[u8; 32] {
        &self.0
    }
}

impl Hasher {
    pub fn new() -> Self {
        Hasher {
            cv: IV,
            chunk_counter: 0,
            buf: [0; BLOCK_LEN],
            buf_len: 0,
            flags: FLAG_CHUNK_START,
        }
    }

    pub fn new_keyed(key: &[u8; 32]) -> Self {
        let mut h = Hasher::new();
        for i in 0..8 {
            h.cv[i] = u32::from_le_bytes([key[i*4], key[i*4+1], key[i*4+2], key[i*4+3]]);
        }
        h.flags |= FLAG_KEYED_HASH;
        h
    }

    pub fn update(&mut self, mut input: &[u8]) {
        while !input.is_empty() {
            if self.buf_len == BLOCK_LEN {
                let mut block = [0u32; 16];
                for i in 0..16 {
                    block[i] = u32::from_le_bytes([
                        self.buf[i*4], self.buf[i*4+1], self.buf[i*4+2], self.buf[i*4+3]
                    ]);
                }
                self.cv = compress_block(&self.cv, &block, self.chunk_counter, BLOCK_LEN as u32, self.flags);
                self.chunk_counter += 1;
                self.buf_len = 0;
                self.flags &= !FLAG_CHUNK_START;
            }

            let n = (BLOCK_LEN - self.buf_len).min(input.len());
            self.buf[self.buf_len..self.buf_len + n].copy_from_slice(&input[..n]);
            self.buf_len += n;
            input = &input[n..];
        }
    }

    pub fn finalize(&self) -> Hash {
        let mut h = self.clone();

        let mut block = [0u32; 16];
        for i in 0..16 {
            let start = i * 4;
            let end = (start + 4).min(h.buf_len);
            let mut bytes = [0u8; 4];
            for j in start..end {
                bytes[j - start] = h.buf[j];
            }
            block[i] = u32::from_le_bytes(bytes);
        }

        let flags = h.flags | FLAG_CHUNK_END | FLAG_ROOT;
        let cv = compress_block(&h.cv, &block, h.chunk_counter, h.buf_len as u32, flags);

        let mut out = [0u8; 32];
        for (i, &w) in cv.iter().enumerate() {
            let bytes = w.to_le_bytes();
            out[i*4..i*4+4].copy_from_slice(&bytes);
        }
        Hash(out)
    }
}

fn compress_block(cv: &[u32; 8], block: &[u32; 16], counter: u64, block_len: u32, flags: u32) -> [u32; 8] {
    let mut state = [0u32; 16];
    state[0..8].copy_from_slice(cv);
    state[8..16].copy_from_slice(&IV);

    state[12] ^= counter as u32;
    state[13] ^= (counter >> 32) as u32;
    state[14] ^= block_len;
    state[15] ^= flags;

    for round in 0..7 {
        let m = &SIGMA[round];

        g(&mut state, 0, 4, 8, 12, block[m[0]], block[m[1]]);
        g(&mut state, 1, 5, 9, 13, block[m[2]], block[m[3]]);
        g(&mut state, 2, 6, 10, 14, block[m[4]], block[m[5]]);
        g(&mut state, 3, 7, 11, 15, block[m[6]], block[m[7]]);

        g(&mut state, 0, 5, 10, 15, block[m[8]], block[m[9]]);
        g(&mut state, 1, 6, 11, 12, block[m[10]], block[m[11]]);
        g(&mut state, 2, 7, 8, 13, block[m[12]], block[m[13]]);
        g(&mut state, 3, 4, 9, 14, block[m[14]], block[m[15]]);
    }

    let mut out = [0u32; 8];
    for i in 0..8 {
        out[i] = cv[i] ^ state[i] ^ state[i + 8];
    }
    out
}

fn g(state: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize, x: u32, y: u32) {
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(x);
    state[d] = (state[d] ^ state[a]).rotate_right(16);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(12);
    state[a] = state[a].wrapping_add(state[b]).wrapping_add(y);
    state[d] = (state[d] ^ state[a]).rotate_right(8);
    state[c] = state[c].wrapping_add(state[d]);
    state[b] = (state[b] ^ state[c]).rotate_right(7);
}

pub fn hash(data: &[u8]) -> Hash {
    let mut h = Hasher::new();
    h.update(data);
    h.finalize()
}

pub fn keyed_hash(key: &[u8; 32], data: &[u8]) -> Hash {
    let mut h = Hasher::new_keyed(key);
    h.update(data);
    h.finalize()
}

pub fn derive_key(context: &str, key_material: &[u8]) -> [u8; 32] {
    let mut h = Hasher::new();
    h.flags |= FLAG_DERIVE_KEY;
    h.update(context.as_bytes());
    h.update(key_material);
    let mut out = [0u8; 32];
    out.copy_from_slice(&h.finalize().0);
    out
}
